const r = await api.get('/mails', { customer_id: 'C005' });
if (!r.items || r.items.length === 0) {
  return '해당 고객이 보낸 메일이 없습니다.';
}
// Assuming first mail is needed
return r.items.map(m => m.subject).join('\n');

